       "kind": {
        "type": "string",
        "enum": [
         "search_console_reconnect",
         "payment_problem",
         "page_down",
         "agent_access_request",
         "missing_links",
         "disavow_upload",
         "disavow_suggestions",
         "renewals_due",
         "plan_limit",
         "cant_reach_lasting",
         "review_found_links",
         "review_stopped_scan",
         "review_stopped_analysis",
         "review_internal_link_findings",
         "verify_internal_link_changes",
         "setup_add_links",
         "setup_connect_agent",
         "setup_search_console"
        ]
       },
       "group": {
        "type": "string",
        "enum": [
         "needs_you",
         "setup"
        ]
       },
       "priority": {
        "type": "string",
        "enum": [
         "urgent",
         "normal",
         "low",
         "setup"
        ]
       },
       "projectId": {
        "type": [
         "string",
         "null"
        ]
       },
       "website": {
        "description": "The website domain; null for a workspace task.",
        "type": [
         "string",
         "null"
        ]
       },
       "who": {
        "type": "string",
        "enum": [
         "you",
         "owner",
         "agent_or_you",
         "only_you"
        ],
        "description": "Who can act: you (a member with write access), owner, agent_or_you or only_you (the person's own sign-in elsewhere)."
       },
       "canAct": {
        "type": "boolean",
        "description": "Whether the person behind this credential can act, from their workspace role. agent.can says whether their agent can."
       },
